namespace Kairnfall.Core;

/// <summary>Reward-free tutorial milestones recorded by the authoritative engine.</summary>
public static class TutorialProgress
{
    public sealed record Lesson(string Id,string Title,string Hint,string Page="");
    public static readonly IReadOnlyList<Lesson> Lessons=Array.AsReadOnly(new Lesson[]
    {
        new("move","Walk through the village","Use {move_up}/{move_left}/{move_down}/{move_right} or the arrow keys. Walk toward the central square."),
        new("talk","Meet the village innkeeper","Approach the innkeeper north of the square. Press {interact} when the Talk prompt appears."),
        new("inventory","Open your backpack","Press {inventory}. Select an item to read its requirements and available actions.","Inventory"),
        new("equip","Try your equipment","Your starter weapon is equipped. Unequip it, then equip it again using its button, double-click, or right-click menu.","Inventory"),
        new("attack","Make a basic attack","Find a field creature outside the village. Press {basic_attack} nearby. Hold the key to repeat attacks."),
        new("cast","Use a starter ability","Select a creature and press 1. Your starter ability is already assigned. Hover over its icon for cost, range, and effect.","Abilities"),
        new("loot","Collect a creature drop","Defeat a creature. Press {interact} near its dropped loot. The pickup feed shows the item icon, name, and quantity."),
        new("skill","Train a skill","Combat and gathering award skill XP. All skill XP contributes to overall level. Open Skills to read training actions.","Skills"),
        new("wood","Gather wood","Find an available tree near the village. Press {interact} when Chop appears. Your backpack contains a woodcutter's axe."),
        new("ore","Mine an ore vein","Find a low-level ore vein. Press {interact} when Mine appears. Your backpack contains a copper pickaxe."),
        new("craft","Craft something useful","Choose a recipe in Crafting. Read its materials and station. Wooden Handle is an early equipment component.","Crafting"),
        new("shop","Trade with a shop","Talk to the provisioner or smith. Buy a useful item or sell unneeded unequipped items. Read the price first."),
        new("map","Find the road onward","Open the map. The route from Wayfarer's Rest goes through Kingsmeadow toward Dawnreach.","Map"),
        new("quest","Complete village work","Accept work from a village NPC. Complete its objectives, then return and claim the reward.","Quests"),
        new("enter_building","Enter a service building","Approach a village door and press {interact}. The inn, smithy, store, and workshop have indoor staff."),
        new("exit_building","Return outdoors","Use the interior exit to return to the village through the normal connected-world transition."),
        new("recovery","Read the recovery rules","Open Guide and read about death, respawn, and repair. You do not have to die to complete this lesson.","Guide"),
        new("leave","Take the Kingsmeadow road","Use the Kingsmeadow exit when ready. Follow the connected road toward Dawnreach.")
    });
    public static bool IsLocalHint(string id)=>id is "inventory" or "map" or "recovery";
    public static bool Record(Character player,string id)
    {
        if(IsLocalHint(id)||!Lessons.Any(lesson=>lesson.Id==id)) return false;
        return player.Tutorial.Add(id);
    }
    public static void RecordAccepted(Character player,Character previous,GameCommand command,Catalog data,RealmState state)
    {
        switch(command.Kind)
        {
            case "talk": Record(player,"talk"); break;
            case "equip": Record(player,"equip"); break;
            case "attack": Record(player,"attack"); break;
            case "cast": Record(player,"cast"); break;
            case "loot": Record(player,"loot"); break;
            case "craft": Record(player,"craft"); break;
            case "buy": case "sell": Record(player,"shop"); break;
            case "claim_quest": Record(player,"quest"); break;
            case "gather":
                if(state.Nodes.TryGetValue(command.Target,out var node))
                {
                    var resource=data.Resources.FirstOrDefault(value=>value.Id==node.Template);
                    if(resource?.Skill=="woodcutting") Record(player,"wood");
                    if(resource?.Skill=="mining") Record(player,"ore");
                }
                break;
            case "transition":
                if(data.Zone(player.Zone).Kind=="interior") Record(player,"enter_building");
                if(data.Zone(previous.Zone).Kind=="interior"&&data.Zone(player.Zone).Kind!="interior") Record(player,"exit_building");
                if(previous.Zone=="wayfarers_rest"&&player.Zone=="kingsmeadow") Record(player,"leave");
                break;
        }
        if(player.SkillXp.Any(pair=>pair.Value>previous.SkillXp.GetValueOrDefault(pair.Key))) Record(player,"skill");
    }
}

